<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      color-scheme: light;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: #f4f6f8;
      color: #1f2937;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 24px;
    }

    main {
      width: min(900px, 100%);
      margin: 0 auto;
    }

    h1, h2 {
      margin-top: 0;
    }

    .panel {
      margin-bottom: 20px;
      padding: 20px;
      border: 1px solid #d8dee6;
      border-radius: 10px;
      background: #fff;
      box-shadow: 0 2px 8px rgba(31, 41, 55, 0.05);
    }

    .form-grid,
    .filter-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    label {
      display: flex;
      flex-direction: column;
      gap: 6px;
      font-weight: 600;
    }

    input,
    select,
    button {
      min-height: 42px;
      padding: 9px 11px;
      border: 1px solid #b8c0cc;
      border-radius: 6px;
      background: #fff;
      color: inherit;
      font: inherit;
    }

    input:focus,
    select:focus,
    button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.2);
      border-color: #2563eb;
    }

    button {
      cursor: pointer;
      font-weight: 700;
    }

    #add-expense {
      align-self: end;
      border-color: #2563eb;
      background: #2563eb;
      color: #fff;
    }

    #add-expense:hover {
      background: #1d4ed8;
    }

    #form-error {
      min-height: 1.4em;
      margin: 12px 0 0;
      color: #b91c1c;
      font-weight: 600;
    }

    .summary {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 10px;
    }

    .summary-card {
      padding: 14px;
      border-radius: 8px;
      background: #eef2f7;
      text-align: center;
    }

    .summary-card strong,
    .summary-card span {
      display: block;
    }

    .summary-card span {
      margin-top: 5px;
      font-size: 1.1rem;
      font-weight: 700;
    }

    #expense-list {
      display: grid;
      gap: 10px;
    }

    .expense {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr 2fr auto;
      gap: 12px;
      align-items: center;
      padding: 13px;
      border: 1px solid #dde2e8;
      border-radius: 8px;
    }

    .expense-amount {
      font-weight: 800;
    }

    .expense-category {
      text-transform: capitalize;
    }

    .expense-note {
      overflow-wrap: anywhere;
      color: #4b5563;
    }

    .exp-del {
      min-height: 36px;
      padding: 7px 11px;
      border-color: #dc2626;
      color: #b91c1c;
    }

    .exp-del:hover {
      background: #fee2e2;
    }

    #empty-message {
      margin: 0;
      padding: 20px;
      color: #6b7280;
      text-align: center;
    }

    @media (max-width: 700px) {
      body {
        padding: 12px;
      }

      .form-grid,
      .filter-grid,
      .summary {
        grid-template-columns: 1fr;
      }

      .expense {
        grid-template-columns: 1fr 1fr;
      }

      .expense-note {
        grid-column: 1 / -1;
      }

      .exp-del {
        grid-column: 1 / -1;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Personal Expense Tracker</h1>

    <section class="panel" aria-labelledby="entry-title">
      <h2 id="entry-title">Add an expense</h2>
      <form id="expense-form" novalidate>
        <div class="form-grid">
          <label for="amount">
            Amount
            <input id="amount" name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" required>
          </label>

          <label for="category">
            Category
            <select id="category" name="category">
              <option value="groceries">Groceries</option>
              <option value="transport">Transport</option>
              <option value="bills">Bills</option>
              <option value="fun">Fun</option>
            </select>
          </label>

          <label for="date">
            Date
            <input id="date" name="date" type="date" required>
          </label>

          <label for="note">
            Note (optional)
            <input id="note" name="note" type="text" maxlength="200" placeholder="What was this for?">
          </label>

          <button id="add-expense" type="submit">Add expense</button>
        </div>
        <p id="form-error" role="alert" aria-live="polite"></p>
      </form>
    </section>

    <section class="panel" aria-labelledby="filter-title">
      <h2 id="filter-title">Filters</h2>
      <div class="filter-grid">
        <label for="filter-category">
          Category
          <select id="filter-category">
            <option value="all">All categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label for="filter-from">
          From
          <input id="filter-from" type="date">
        </label>

        <label for="filter-to">
          To
          <input id="filter-to" type="date">
        </label>
      </div>
    </section>

    <section class="panel" aria-labelledby="summary-title">
      <h2 id="summary-title">Visible summary</h2>
      <div class="summary">
        <div class="summary-card">
          <strong>Total</strong>
          <span id="total">0.00</span>
        </div>
        <div class="summary-card">
          <strong>Groceries</strong>
          <span class="cat-total" data-cat="groceries">0.00</span>
        </div>
        <div class="summary-card">
          <strong>Transport</strong>
          <span class="cat-total" data-cat="transport">0.00</span>
        </div>
        <div class="summary-card">
          <strong>Bills</strong>
          <span class="cat-total" data-cat="bills">0.00</span>
        </div>
        <div class="summary-card">
          <strong>Fun</strong>
          <span class="cat-total" data-cat="fun">0.00</span>
        </div>
      </div>
    </section>

    <section class="panel" aria-labelledby="list-title">
      <h2 id="list-title">Expenses</h2>
      <div id="expense-list"></div>
      <p id="empty-message">No expenses yet.</p>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const STORAGE_KEY = "personal-expense-tracker-expenses";
      const categories = ["groceries", "transport", "bills", "fun"];

      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const formError = document.getElementById("form-error");
      const filterCategory = document.getElementById("filter-category");
      const filterFrom = document.getElementById("filter-from");
      const filterTo = document.getElementById("filter-to");
      const expenseList = document.getElementById("expense-list");
      const emptyMessage = document.getElementById("empty-message");
      const totalElement = document.getElementById("total");

      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (!Array.isArray(stored)) return [];

          return stored.filter(expense =>
            expense &&
            typeof expense.id === "string" &&
            Number.isFinite(Number(expense.amount)) &&
            Number(expense.amount) > 0 &&
            categories.includes(expense.category) &&
            typeof expense.date === "string" &&
            expense.date
          ).map(expense => ({
            id: expense.id,
            amount: Number(expense.amount),
            category: expense.category,
            date: expense.date,
            note: typeof expense.note === "string" ? expense.note : ""
          }));
        } catch {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
      }

      function makeId() {
        return Date.now().toString(36) + Math.random().toString(36).slice(2);
      }

      function isVisible(expense) {
        const categoryMatches =
          filterCategory.value === "all" ||
          expense.category === filterCategory.value;
        const fromMatches = !filterFrom.value || expense.date >= filterFrom.value;
        const toMatches = !filterTo.value || expense.date <= filterTo.value;
        return categoryMatches && fromMatches && toMatches;
      }

      function render() {
        expenseList.replaceChildren();

        const visibleTotals = Object.fromEntries(
          categories.map(category => [category, 0])
        );
        let visibleTotal = 0;
        let visibleCount = 0;

        expenses.forEach(expense => {
          const row = document.createElement("div");
          row.className = "expense";
          row.dataset.id = expense.id;

          const amount = document.createElement("span");
          amount.className = "expense-amount";
          amount.textContent = "$" + expense.amount.toFixed(2);

          const category = document.createElement("span");
          category.className = "expense-category";
          category.textContent = expense.category;

          const date = document.createElement("time");
          date.dateTime = expense.date;
          date.textContent = expense.date;

          const note = document.createElement("span");
          note.className = "expense-note";
          note.textContent = expense.note || "—";

          const deleteButton = document.createElement("button");
          deleteButton.type = "button";
          deleteButton.className = "exp-del";
          deleteButton.textContent = "Delete";
          deleteButton.setAttribute(
            "aria-label",
            "Delete " + expense.category + " expense of $" + expense.amount.toFixed(2)
          );

          row.append(amount, category, date, note, deleteButton);

          if (!isVisible(expense)) {
            row.hidden = true;
          } else {
            visibleCount += 1;
            visibleTotal += expense.amount;
            visibleTotals[expense.category] += expense.amount;
          }

          expenseList.appendChild(row);
        });

        totalElement.textContent = visibleTotal.toFixed(2);

        document.querySelectorAll(".cat-total").forEach(element => {
          const category = element.dataset.cat;
          element.textContent = visibleTotals[category].toFixed(2);
        });

        emptyMessage.hidden = visibleCount !== 0;
        emptyMessage.textContent = expenses.length
          ? "No expenses match the current filters."
          : "No expenses yet.";
      }

      form.addEventListener("submit", event => {
        event.preventDefault();

        const rawAmount = amountInput.value.trim();
        const amount = Number(rawAmount);
        const date = dateInput.value;

        if (rawAmount === "" || !Number.isFinite(amount) || amount <= 0) {
          formError.textContent = "Enter an amount greater than zero.";
          amountInput.focus();
          return;
        }

        if (!date) {
          formError.textContent = "Choose a date.";
          dateInput.focus();
          return;
        }

        expenses.unshift({
          id: makeId(),
          amount,
          category: categoryInput.value,
          date,
          note: noteInput.value.trim()
        });

        saveExpenses();
        formError.textContent = "";
        amountInput.value = "";
        noteInput.value = "";
        render();
        amountInput.focus();
      });

      expenseList.addEventListener("click", event => {
        const deleteButton = event.target.closest(".exp-del");
        if (!deleteButton) return;

        const row = deleteButton.closest(".expense");
        expenses = expenses.filter(expense => expense.id !== row.dataset.id);
        saveExpenses();
        render();
      });

      [filterCategory, filterFrom, filterTo].forEach(control => {
        control.addEventListener("change", render);
        control.addEventListener("input", render);
      });

      render();
    })();
  </script>
</body>
</html>
